def is_woodall(n):
    def digits_product(x):
        product = 1
        for digit in str(x):
            product *= int(digit)
        return product

    previous = []
    while n not in previous:
        previous.append(n)
        n = digits_product(n)

    return n == 1

def is_woodall(n):
    def digits_product(x):
        product = 1
        for digit in str(x):
            product *= int(digit)
        return product

    previous = set()
    while n != 1 and n not in previous:
        previous.add(n)
        n = digits_product(n)

    return n == 1

def is_woodall(n):
    if n < 1:
        return False
    product = 1
    while n > product:
        product *= n % 10
        n //= 10
    return n == product

def is_woodall(n):
    if n < 1:
        return False
    digits = [int(d) for d in str(n)]
    product = 1
    for d in digits:
        if d == 0:
            return False
        product *= d
    return product == n

def is_octagonal(num):
    n = 1
    while True:
        oct_num = n*(7*n-5)//2
        if oct_num == num:
            return True
        elif oct_num > num:
            return False
        n += 1

